package com.weatherapp.servlet;import com.weatherapp.util.Json;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/api/me") public class MeServlet extends BaseServlet{protected void doGet(HttpServletRequest r,HttpServletResponse s)throws IOException{try{HttpSession x=requireSession(r,s);Json.write(s,Map.of("name",x.getAttribute("UserName"),"cityId",x.getAttribute("UserCityID")));}catch(Exception e){s.setStatus(401);Json.write(s,Map.of("message",e.getMessage()));}}}
